export type Tone = 'casual' | 'polite'
export type MiniSeed = readonly [
  title: string,
  casualQuestion: string,
  casualAnswer: string,
  politeQuestion: string,
  politeAnswer: string,
  englishQuestion: string,
  englishAnswer: string,
]

export type DialogueLine = { speaker: 'A' | 'B'; japanese: string; english: string }
export type Conversation = {
  id: string
  title: string
  casual: DialogueLine[]
  polite: DialogueLine[]
  keyPhrase: string
  keyMeaning: string
}
export type Topic = {
  id: string
  number: string
  icon: string
  title: string
  japanese: string
  description: string
  color: string
  conversations: Conversation[]
}

type TopicSeed = {
  id: string
  icon: string
  title: string
  japanese: string
  description: string
  color: string
  lessons: readonly MiniSeed[]
}

