export const topics: Topic[] = topicSeeds.map((topic, topicIndex) => ({
  ...topic,
  number: String(topicIndex + 1).padStart(2, '0'),
  conversations: topic.lessons.map((item, lessonIndex) => ({
    id: `${topic.id}-${lessonIndex + 1}`,
    title: item[0],
    casual: [
      { speaker: 'A', japanese: item[1], english: item[5] },
      { speaker: 'B', japanese: item[2], english: item[6] },
    ],
    polite: [
      { speaker: 'A', japanese: item[3], english: item[5] },
      { speaker: 'B', japanese: item[4], english: item[6] },
    ],
    keyPhrase: item[1],
    keyMeaning: item[5],
  })),
}))

export const conversationCount = topics.reduce((sum, topic) => sum + topic.conversations.length, 0)
